+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { t } from "../i18n/messages.js";
+
+/** Imports validated sale rows atomically, skipping tickets already recorded. */
+export function recordSales(store, rows) {
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    if (existing.has(row.ticket)) continue;
+    try {
+      const dish = staged.data.dishes.find((d) => d.id === row.dishId);
+      if (!dish) throw new AppError("bad_request", { reason: "unknown dish" });
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), row.qty);
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0)
+          consume(staged, ingredient.itemId, ingredient.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      }
+      staged.data.sales.push({
+        id: staged.nextId("sale"), ticket: row.ticket, soldAt: row.soldAt,
+        dishId: row.dishId, qty: row.qty, ingredients,
+      });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("sales_row", { row: row.row, reason: t(error.code, "en", error.params) });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
